"""集中调参入口。

这里放策略、走位、踢球和避障的可调参数。数值迁移自当前代码文件,
以后优先在本文件调整参数。

注释约定:每个配置项定义行上方为三行块注释:
  # 作用: 该参数控制什么(单位:米/秒/弧度/度/秒数/无量纲,已逐项注明)
  # 影响: 哪些行为/模块/函数受其影响
  # 建议: 推荐取值范围 + 当前值评价/调整方向
场地基准:14×9m(半长 7.0/半宽 4.5),门宽 2.6(半宽 1.3),中圈半径 1.5,
禁区 3.0×6.0,小禁区 1.0×4.0,控制频率 30Hz。
"""

from __future__ import annotations

import math


# ======================================================================
# 踢球力度
# ======================================================================
# 本节总览:踢球力度统一经 Player.kick() 夹取到 [KICK_POWER_MIN, KICK_POWER_MAX]
# 后交给 SDK SoccerKickManager;SDK 合法力度范围 1.0–10.0,越界抛 ValueError。

# 作用: kick() 力度下限夹取(无量纲),低于该值的力度被抬高到该值。
# 影响: 所有踢球的最小力度(player.py kick() 内 power_clamped)。
# 建议: [1.0, 2.0]。SDK SoccerKickManager.update_command 合法力度范围 1.0–10.0,
#   越界抛 ValueError;原值 0.1 低于 SDK 下限;现役调用均 ≥1.85,
#   故取 1.0 对齐 SDK 下限,此修正不改变当前行为。
KICK_POWER_MIN = 1.0

# 作用: kick() 力度上限夹取(无量纲),高于该值的力度被压低到该值。
# 影响: 所有踢球的最大力度(player.py kick() 内 power_clamped)。
# 建议: [6.0, 10.0]。保持 10.0,即 SDK 合法上限。
KICK_POWER_MAX = 10.0

# 作用: 力度表空/pose 缺失时的兜底标量力度(无量纲),亦 kick() 的默认实参。
# 影响: normal 射门兜底力度;player.py plan_kick() 查表失败时退回该值。
# 建议: [1.5, 3.0]。保持 1.85(近距可控射门档位)。
KICK_POWER_DEFAULT = 1.85

# 作用: 我方中场开球/任意球第一脚的统一力度(无量纲),不走 x 力度表。
# 影响: main.py 的 _act_our_kickoff / _act_our_set_play_limited(角球另用 CORNER_KICK_POWER)。
# 建议: [4.0, 10.0]。保持 8.92,即开球/任意球第一脚统一力度(需踢远,力度显著高于 normal 射门)。
KICK_POWER_OUR_KICKOFF = 8.92

# 作用: normal play 按踢球者 team 视角 x 分段查力度(后场狠解围、门前轻射)。
# 影响: 经 kick_power_for_x() → player.py plan_kick() 影响所有 normal 射门/解围力度。
# 建议: 每行 power∈[1.0, 10.0];行须连续且 x 升序(框架不校验,自行保证)。
#   保持现形态(对方门前最后一行 1.5–2.0 轻射、后场 6–8 狠解围)。
# 表格式:每行 (x_lo, x_hi, power),闭区间;team 视角 x 进攻方向为 +x,
# 场地半长 7.0m, x∈[-7, +7]。x 低于首行 x_lo → 取首行 power;
# 高于末行 x_hi → 取末行 power(端点行 clamp)。
# 仅用于 normal play;开球/任意球第一脚用 KICK_POWER_OUR_KICKOFF(角球用 CORNER_KICK_POWER、边线球用 THROW_IN_KICK_POWER_*)。
KICK_POWER_BY_X: tuple[tuple[float, float, float], ...] = (
    (-7.0, -3.0, 7.72),
    (-3.0,  0.5, 5.02),
    ( 0.5,  2.0, 4.90),
    ( 2.0,  5.0, 4.90),
    ( 5.0,  6.0, 4.90),
    ( 6.0,  7.0, 1.85),
)

# 作用: 大/小接近角力度表分界角(度);接近角 < 该值查 NARROW 表,否则查 WIDE 表。
APPROACH_ANGLE_SPLIT_DEG = 35.0

# 作用: 小角度接近(<APPROACH_ANGLE_SPLIT_DEG,正对球)的踢球力度表,结构与 KICK_POWER_BY_X 相同;初始逐段复制该表。
KICK_POWER_BY_X_NARROW: tuple[tuple[float, float, float], ...] = (
    (-7.0, -3.0, 7.72),
    (-3.0,  0.5, 4.90),
    ( 0.5,  2.0, 4.90),
    ( 2.0,  5.0, 4.90),
    ( 5.0,  6.0, 4.90),
    ( 6.0,  7.0, 1.85),
)

# 作用: 大角度接近(≥APPROACH_ANGLE_SPLIT_DEG,侧面接近)的踢球力度表,结构与 KICK_POWER_BY_X 相同;初始逐段复制,待单独调参。
KICK_POWER_BY_X_WIDE: tuple[tuple[float, float, float], ...] = (
    (-7.0, -3.0, 7.72),
    (-3.0,  0.5, 5.02),
    ( 0.5,  2.0, 5.02),
    ( 2.0,  5.0, 5.02),
    ( 5.0,  6.0, 4.90),
    ( 6.0,  7.0, 1.85),
)


def _lookup_kick_power_table(
    kicker_x: float,
    rows: tuple[tuple[float, float, float], ...],
) -> float:
    """KICK_POWER_BY_X 系力度表的公共查表实现。

    对 rows 线性扫描:kicker_x 低于首行 start 返回首行 power，高于末行
    end 返回末行 power(端点行 clamp)。假定行连续、升序，不做校验。表为空时
    退回标量 KICK_POWER_DEFAULT，让配置错误优雅降级。相邻行共享端点时(如一行
    到 -3.0、下一行从 -3.0 起)，边界点上返回低索引行的 power。
    """
    if not rows:
        return KICK_POWER_DEFAULT
    first_start, _, first_power = rows[0]
    if kicker_x < first_start:
        return first_power
    _, last_end, last_power = rows[-1]
    if kicker_x > last_end:
        return last_power
    for start, end, power in rows:
        if start <= kicker_x <= end:
            return power
    return last_power


# 作用: 按踢球者 team 视角 x 返回 normal play 踢球力度(无量纲)。
# 影响: player.py plan_kick() 调用,决定所有 normal 射门/解围的力度。
# 建议: 查询函数,无取值可调;语义=对 KICK_POWER_BY_X 线性扫描,
#   端点外取端行值,表空回退 KICK_POWER_DEFAULT(详见 _lookup_kick_power_table)。
def kick_power_for_x(kicker_x: float) -> float:
    """按踢球者 team-view x 返回 normal play 踢球力度(公共查表见 _lookup_kick_power_table)。"""
    return _lookup_kick_power_table(kicker_x, KICK_POWER_BY_X)


# 作用: 按踢球者 team 视角 x + 接近角返回 normal play 踢球力度(无量纲);接近角分档选 NARROW/WIDE 双表。
# 影响: player.py attack() 起脚经 plan_kick(approach_angle_deg=...) 调用。
# 建议: 查询函数,无取值可调;分界角见 APPROACH_ANGLE_SPLIT_DEG,表内查询与 kick_power_for_x 同一实现。
def kick_power_for_x_and_angle(x: float, approach_angle_deg: float) -> float:
    """按接近角选表后查力度。

    approach_angle_deg < APPROACH_ANGLE_SPLIT_DEG 查 KICK_POWER_BY_X_NARROW
    (小角度/正对球),否则查 KICK_POWER_BY_X_WIDE(大角度/侧面接近)。表内查询
    (端点 clamp、空表退回 KICK_POWER_DEFAULT)与 kick_power_for_x 共用同一实现。
    """
    rows = (
        KICK_POWER_BY_X_NARROW
        if approach_angle_deg < APPROACH_ANGLE_SPLIT_DEG
        else KICK_POWER_BY_X_WIDE
    )
    return _lookup_kick_power_table(x, rows)


# ======================================================================
# Player 走位控制
# ======================================================================
# 本节总览:walk_to() 位置闭环的核心参数——到位阈值、全向切换距离、速度上限与比例增益。

# 作用: walk_to 到达判定阈值(米),距目标 ≤ 该值即认定到位(默认实参)。
# 影响: 所有走位的到位判定与终点收敛精度(全库 9 处 walk_to 调用)。
# 建议: [0.05, 0.30] 米。保持 0.15:30Hz 控制下太小会过冲振荡、太大站位不准。
ARRIVE_DIST = 0.15

# 作用: 距目标 ≤ 该值(米)时切全向近距控制,否则远距离边走边转。
# 影响: walk_to 最后逼近行为(含朝向收敛,见 player.py walk_to 两分支)。
# 建议: [0.5, 1.5] 米。保持 1.0。
OMNI_DIST = 1.0

# 作用: 平移速度指令上限(米/秒)。
# 影响: 全体机器人所有移动的线速度上限(walk_to 内统一截断)。
# 建议: [1.0, 2.0] 米/秒。保持 2.0:超物理极速只会饱和,调低可换稳定。
MAX_LINEAR = 2.0

# 作用: 转向角速度指令上限(弧度/秒)。
# 影响: 所有原地转/边走边转(_angular() 的夹取上限)。
# 建议: [1.0, 3.0] 弧度/秒。保持 2.0。
MAX_ANGULAR = 2.0

# 作用: 平移 P 增益(1/秒);近距=增益×剩余位移,远距=增益×距离×cos²角差。
# 影响: 所有走位的加减速节奏。
# 建议: [0.8, 2.5] 1/秒。保持 1.5:配 MAX_LINEAR=2.0 时 1.33m 外即满速。
LINEAR_GAIN = 1.5

# 作用: 转向 P 增益(1/秒),角速度=clamp(增益×角差, ±MAX_ANGULAR)。
# 影响: 所有朝向控制(面向球/目标/射门朝向)。
# 建议: [1.0, 4.0] 1/秒。保持 2.0。
ANGULAR_GAIN = 2.0


# ======================================================================
# Player 踢球 / 射门规划
# ======================================================================
# 本节总览:追球走位与 SDK 自动起脚的切换阈值(带迟滞),以及绕后站位距离。

# 作用: 距球 ≤ 该值(米)才进入踢球状态(底盘交给 SoccerKickManager)。
# 影响: attacker 从追球切到 SDK 自动起脚的时机(player.py attack 流程)。
# 建议: [1.0, 2.0] 米。保持 1.2;最优值取决于 SDK 接近行为,可在仿真对比微调。
KICK_ENTER_M = 1.4

# 作用: 踢球状态中距球 > 该值(米)才退出(迟滞上界 > ENTER,防抖)。
# 影响: 踢球状态保持范围,防边界附近状态来回翻转。
# 建议: KICK_ENTER_M + [0.2, 0.6] 米。保持 1.8。
KICK_EXIT_M = 1.8

# 作用: 我方开球(OUR_KICKOFF)专用的踢球进入距离门(米);开球主罚者距球 ≤ 该值才起脚。
# 影响: 仅 main.py _act_our_kickoff 的 attack 调用;其他 phase 继续用 KICK_ENTER_M。
