KICK_ENTER_OUR_KICKOFF_M = 1.2

# 作用: 我方开球专用的踢球退出距离门(米);迟滞上界,须 > KICK_ENTER_OUR_KICKOFF_M。
# 影响: 仅开球主罚者的踢球状态保持范围。
# 建议: KICK_ENTER_OUR_KICKOFF_M + [0.2, 0.6] 米。当前保持 1.8(与全局一致,行为不变)。
KICK_EXIT_OUR_KICKOFF_M = 1.8

# 作用: 追球站位点=球→瞄准点连线上、球身后该距离(米),到位天然对准射门方向。
# 影响: normal 进攻、守门出击解围、任意球/角球主罚的绕后站位。
# 建议: [0.25, 0.6] 米。保持 0.35:太小易顶过球、太大起脚行程长。
CHASE_BEHIND_M = 0.35

# 作用: 接近角锥半宽(度);接近角超该值且不在踢球状态时,attack() 先绕到球后锚点、不直冲。
CHASE_APPROACH_CONE_DEG = 80.0

# 作用: 锥门限迟滞带宽(度);退出绕后需接近角 < CHASE_APPROACH_CONE_DEG - 该值,防边界抖动。
CHASE_APPROACH_CONE_HYST_DEG = 3.0

# 作用: 锥角度/绕后锚点用的固定球门参考点 x(米),不随球位动态变化。
CHASE_CONE_GOAL_X = 7.6

# 作用: 锥角度/绕后锚点用的固定球门参考点 y(米),门中心线。
CHASE_CONE_GOAL_Y = 0.0


# ======================================================================
# Player 技术动作参数：守门 / 支援
# ======================================================================
# 本节总览:守门员站位/出击/门线横移预判,以及 support 无威胁时的补防站位。

# 作用: 守门站 home 时是否面向球(bool;否则朝 +x)。
# 影响: 守门员待机朝向与扑救反应速度。
# 建议: 保持 True(面向球反应更快)。
GUARD_FACE_BALL = True

# 作用: 守门员默认站位 x(米),站位=(该值, 0);我方门线在 x=-7,此处前推 0.5。
# 影响: 守门员所有非出击站位 + 边线球守门员就位判定目标。
# 建议: [-6.9, -6.0] 米。保持 -6.5:靠前易拦截低平球、太靠前易被吊射。
GUARD_HOME_X = -6.5

# 作用: 出击阈值(米),球.x < 该值时守门员从 home 切到 attack() 出击解围。
# 影响: 守门员"守门/出击"切换点(出击后踢向对方门解围)。
# 建议: [-4.0, -0.5] 米。保持 -2.0:越负越保守(球越接近我方门才出击)。
GUARD_CHARGE_X = -2.0

# 作用: 出击迟滞带(米),已出击时球.x < GUARD_CHARGE_X+该值才保持出击。
# 影响: 防止出击边界反复进出(退出出击需球回到迟滞带外)。
# 建议: [0.2, 1.0] 米。保持 0.5。
GUARD_CHARGE_HYST_M = 0.5

# --- 守门员门线横向移动(封堵超远射门:按球速射线交点预判) ---
# 球在非出击区时,守门员用相邻帧球位差分估计球速向量,求射线与竖直预判线
# x = GUARD_HOME_X + PRE_LEN_M 的交点 y_guard,实时走到 (GUARD_HOME_X, y_guard)。
# 复用 BALL_SPEED_EPS 判定远射威胁:球朝我方门的接近速度 -vbx > BALL_SPEED_EPS
# 且交点在未来才跟踪,否则回退门线中心 y=0;y_guard 用 GOALIE_MAX_Y_OFFSET 对称钳位。

# 作用: 门线预判线相对 GUARD_HOME_X 的前移量(米),预判线 x = GUARD_HOME_X + PRE_LEN_M。
# 影响: 远射预判扑救的横移目标线位置(player.py guard())。
# 建议: [0.0, 1.0] 米。保持 0.5。
PRE_LEN_M = 0.5

# 作用: 守门员沿门线横移的对称钳位 ±值(米)。
# 影响: 远射预判最大横向偏离(门半宽 1.3,超 1.3 会站出门框)。
# 建议: [0.5, 1.3] 米。保持 1.0。
GOALIE_MAX_Y_OFFSET = 1.0

# 作用: 无威胁对手时 support:cover 站位=球→己方门连线上距球该距离(米)。
# 影响: 第三人日常补防位置(player.py support())。
# 建议: [1.5, 4.0] 米。保持 3.0。
SUPPORT_DIST_M = 3.0

# ======================================================================
# Normal 阶段策略
# ======================================================================

