# 作用: 外推位移上限(米),防噪声速度被放大。
# 影响: 预测点最大偏移(_predict_ball_xy / attack 拦截分支)。
# 建议: [2.0, 8.0] 米。保持 7.0(≈半场长)。
BALL_PREDICT_MAX_M = 7.0

# 作用: 球速低于该值视为静止(米/秒)。
# 影响: 球动/静判定的全部下游:预测、拦截、守门横移、对方开球 hold 判据。
# 建议: [0.1, 0.4] 米/秒。保持 0.2:30Hz 静止真值抖动约 ±0.1–0.3,太小被噪声误判。
BALL_SPEED_EPS = 0.2

# 作用: normal 瞄准提前量(秒),aim = ball + v×该值(≈SDK 收尾时间)。
# 影响: 滚动球射门/解围的瞄准精度。
# 建议: [0.05, 0.30] 秒。保持 0.15(约 SoccerKickManager.update_ball 收尾时间)。
BALL_KICK_LEAD_SEC = 0.15

# 作用: support:block 站位=威胁对手→我方门连线上距我方门该距离(米)。
# 影响: 第三人封堵射门/传球通道的位置。
# 建议: [0.8, 2.5] 米。保持 1.5:太近挡守门员路线、太远封不住角度。
SUPPORT_BLOCK_GOAL_DIST_M = 1.5

# 作用: 对手 x < 该值(进入我方侧)才算威胁对手、启用封堵(米)。
# 影响: support 封堵(block)/补防(cover)模式切换。
# 建议: [0.0, 4.0] 米。保持 2.0。
SUPPORT_BLOCK_ENABLE_X = 2.0

# 作用: 球被遮挡后仍信任最后已知球位的最长时长(秒)。
# 影响: 球丢失时 attacker 是否去最后已知点搜索(_recent_ball_memory)。
# 建议: [0.5, 2.0] 秒。保持 1.0。
BALL_MEMORY_MAX_AGE_SEC = 1.0

# 作用: 对方控球判定半径(米),最近对手离球 < 该值且不比我方最近者远。
# 影响: 第二逼抢派遣的触发条件(_opponent_has_ball)。
