# 建议: [0.2, 1.0] 米。保持 0.5。
THROW_IN_PLAN_BALL_DRIFT_M = 0.5

# 作用: 发球启动后球离原点超该距离(米)→认定第一脚完成。
# 影响: 防定位球窗口内重复起脚。
# 建议: [0.05, 0.3] 米。保持 0.1。
THROW_IN_COMPLETE_BALL_MOVE_M = 0.1

# 作用: x_advance ≥ 该值(米)视为长传,用大力度档。
# 影响: 边线球长传/短传力度档位选择。
# 建议: [3.5, 5.0] 米。保持 4.35。
THROW_IN_LONG_ADVANCE_M = 4.35

# 作用: 边线球长传力度(无量纲)。
# 影响: x_advance ≥ THROW_IN_LONG_ADVANCE_M 时的踢球力度。
# 建议: [2.5, 5.0],须 ≥ SDK 下限 1.0。保持 3.0。
THROW_IN_KICK_POWER_LONG = 3.0

# 作用: 边线球短传力度(无量纲)。
# 影响: x_advance < THROW_IN_LONG_ADVANCE_M 时的踢球力度。
# 建议: [1.5, 2.5],须 ≥ SDK 下限 1.0。保持 1.85。
THROW_IN_KICK_POWER_SHORT = 1.85


# ======================================================================
# 站位 / 避让
# ======================================================================

# 作用: 对方定位球时把球当成该半径障碍(米),规则 1.5m 禁区 + 余量,防路径贴球穿过。
# 影响: 对方定位球期间所有我方走位路径(经 walk_to 的 ball_clearance_m)。
# 建议: [1.5, 2.0] 米。保持 1.65:低于 1.5 有违规风险。
OPPONENT_RESTART_AVOID_M = 1.65


# ======================================================================
# 踢球目标几何
# ======================================================================
# 本节总览:plan_kick 动态瞄准 x_GOAL 的几何参数(门柱切线、回退与放大),
# 计算实现见 utils/geom.py。

# 作用: 看不到球时回退瞄准 x = 门线 + 该深度(米)。
# 影响: 球丢失时射门瞄准回退。
# 建议: [0.1, 0.5] 米。保持 0.25(瞄准门内一点保证进球判定)。
GOAL_TARGET_DEPTH_M = 0.25

# 作用: 动态瞄准 x_GOAL 计算中的门柱避障圆半径(米,切线几何)。
# 影响: 所有 normal 射门瞄准点。
# 建议: [0.2, 0.5] 米。保持 0.29:越大越保守、瞄准越偏门中。
GOAL_POST_AVOID_RADIUS_M = 0.29

# 作用: 门线后阻挡线段长度(米),过滤穿网假切线。
# 影响: 切线筛选。
# 建议: [0.3, 1.0] 米。保持 0.6(应与 GOAL_DEPTH 一致)。
GOAL_DEPTH_SEG_M = 0.6

# 作用: |y_ball| ≤ 该值(米)视为正对球门(走无切线解回退分支)。
# 影响: 正对门时的瞄准分支选择。
# 建议: [0.3, 1.5] 米。保持 0.8(门半宽 1.3 量级内)。
STRAIGHT_SHOT_Y_THRESHOLD_M = 0.8

# 作用: 底角无射门角度时的回退瞄准 x(米),刚过门线制造朝门打。
# 影响: 底角死角的射门瞄准。
# 建议: [7.0, 7.5] 米。保持 7.05。
CORNER_FALLBACK_X = 7.05

# !! 哨兵值,非场地坐标 !!
# 作用: 正对球门时 x_GOAL = 本值 − x_ball(瞄准远端 +x 等效直线轰门)。
# 影响: 正对门射门的瞄准点计算(无切线解分支①)。
# 建议: 保持 ≥1000 量级;改小会把正对门瞄准拉回场内、改变行为。
X_STRAIGHT_M = 10000.0

# 作用: x_GOAL 放大分界点(米),超该值才按乘子推远瞄准点。
# 影响: 防前场球擦门柱出界的瞄准外推(后场 ≤ 该值不放大)。
# 建议: [7.0, 9.0] 米。保持 7.6(略大于门线 7.0,只放大门后解)。
X_START_MULT = 7.6

# 作用: 放大系数(无量纲),x_return = max((x_GOAL − X_START_MULT)×本值, 0) + x_GOAL。
# 影响: 门后瞄准点的推远幅度。
# 建议: [0.0, 0.3]。保持 0.1;设 0 即关闭放大。
X_MULTIPLYING_FACTOR = 0.1

# ======================================================================
# 障碍物几何参数
# ======================================================================
# 本节总览:障碍物半径与球门建模参数,供 collect_obstacles / 路径规划使用。

# 作用: 默认球障碍半径(米),可被 walk_to 的 ball_clearance_m 覆盖。
# 影响: 所有 avoid_ball 走位(READY 站位、support、守门、定位球绕后)。
# 建议: [0.3, 0.75] 米。保持 0.50:太小贴球犯规风险、太大绕路过远。
BALL_OBSTACLE_RADIUS = 0.50

# 作用: 对手机器人障碍半径(米)。
# 影响: 所有 avoid_robots 走位 + 全局/局部规划器阻挡判定。
# 建议: [0.4, 0.7] 米。保持 0.55(机身半径 + 摆动余量)。
OPPONENT_RADIUS = 0.55

# 作用: 队友机器人障碍半径(米)。
# 影响: avoid_robots 走位中的队友阻挡判定。
# 建议: [0.35, 0.6] 米。保持 0.48。
TEAMMATE_RADIUS = 0.48

# 作用: 通用安全余量(米),障碍「挡路」判定与绕行偏移都加在半径上。
# 影响: 现役引用仅剩 player.py 定位球待命点下限
#   (SET_PLAY_STAGE_M 实际值 ≥ BALL_OBSTACLE_RADIUS + SAFETY_MARGIN)。
# 建议: [0.1, 0.4] 米。保持 0.22。
SAFETY_MARGIN = 0.22

# 作用: 球门 U 形障碍建模深度(米),后柱/后网位于门线 ±(半场长 + 该值)。
# 影响: 两侧球门不可穿越结构,防路径穿门抄近道。
# 建议: [0.3, 0.8] 米。保持 0.6(与物理球门深度一致)。
GOAL_DEPTH = 0.6

# 作用: 门柱障碍圆半径(米),每侧门前后各 2 柱。
# 影响: 球门障碍建模 + 门柱附近路径阻挡。
# 建议: [0.1, 0.3] 米。保持 0.20。
POST_RADIUS = 0.20

# 作用: 球网采样障碍圆半径(米)。
# 影响: 球网离散化障碍建模。
# 建议: [0.2, 0.4] 米。保持 0.35(≥ NET_STEP/2,保证采样圆搭接无缝隙)。
NET_RADIUS = 0.35

# 作用: 球网离散化步长(米)。
# 影响: 球网障碍采样密度。
# 建议: [0.2, 0.5] 米且 ≤ 2×NET_RADIUS。保持 0.35。
NET_STEP = 0.35

# ======================================================================
# 全局路径规划器 (A* Grid Planner)
# ======================================================================
# 本节总览:walk_to 全局 A* 栅格规划(带直线短路)及其节流缓存参数。

# 作用: 是否启用全局 A* 规划器(bool),False 回退局部 VFH。
# 影响: 所有带避障的走位。
# 建议: 保持 True:A* 带直线短路,绕行质量优于 VFH;VFH 留作降级。
USE_GLOBAL_PATH_PLANNER = True

# 作用: A* 栅格分辨率(米/格),亦直线短路采样步长。
# 影响: 路径精细度与计算量(14×9 场地:0.05→约 46k 格、0.10→约 12k、0.15→约 5k)。
# 建议: [0.05, 0.20] 米/格。保持 0.10:0.05 在 Jetson 30Hz 下可能超时。
GLOBAL_GRID_RESOLUTION_M = 0.10

# 作用: 规划区域从场地边界内收的余量(米)。
# 影响: 边界附近路径可行性。
# 建议: [0.1, 0.4] 米。保持 0.20。
GLOBAL_FIELD_MARGIN_M = 0.20

# 作用: 障碍膨胀余量(米),栅格阻挡半径 = 障碍半径 + 该值。
# 影响: 路径与障碍的安全间距。
# 建议: [0.0, 0.25] 米。保持 0.10。
GLOBAL_OBSTACLE_MARGIN_M = 0.10

# 作用: 从缓存路径提取前方追踪点的距离(米)。
# 影响: 路径跟踪平滑度/转弯提前量。
# 建议: [0.2, 0.9] 米。保持 0.3:过大弯道切角。
GLOBAL_PATH_LOOKAHEAD_M = 0.3

# 作用: A* 重规划最小间隔(秒),节流缓存;复用期间仍每帧从缓存路径提取 waypoint。
# 影响: 规划算力开销与障碍响应延迟。
# 建议: [0.03, 0.3] 秒。保持 0.05(30Hz 下约 1.5 帧)。
PLAN_REPLAN_INTERVAL_S = 0.05

# 作用: 目标点移动超该距离(米)强制重算。
# 影响: 目标大幅移动时的重规划触发。
# 建议: [0.2, 1.0] 米。保持 0.5。
PLAN_REPLAN_TARGET_MOVE_M = 0.5

# ======================================================================
# 局部路径规划器 (VFH Direction Scan)
# ======================================================================
# 本节总览:局部 VFH 方向扫描,亦全局规划失败/关闭时的降级路径。

# 作用: 前方探测射线长度(米),局部避障的视觉距离(亦画可视化)。
# 影响: USE_GLOBAL_PATH_PLANNER=False 时的绕行 + 全局规划失败的降级路径。
# 建议: [0.8, 2.0] 米。保持 1.2。
PLAN_LOOKAHEAD = 1.2

# 作用: 候选方向可接受的最小前方余量(米)。
# 影响: VFH 候选方向筛选。
# 建议: [0.2, 0.5] 米。保持 0.35。
PLAN_CLEARANCE = 0.35

# 作用: 候选方向扫描步长(弧度)。
# 影响: VFH 方向分辨率。
# 建议: [5°, 20°](约 0.087–0.35 弧度)。保持 math.radians(15)。
PLAN_STEP = math.radians(15)

# 作用: 扫描最大偏离目标方向的角度(弧度,±)。
# 影响: VFH 绕行搜索范围。
# 建议: [60°, 180°]。保持 math.radians(100)(允许近乎掉头绕行)。
PLAN_MAX_OFFSET = math.radians(100)

# ======================================================================
# 可视化
# ======================================================================

# 作用: 踢球目标 X 标记的半尺寸(米)。
# 影响: 仅调试可视化(ROS MarkerArray),无行为影响。
# 建议: [0.1, 0.3] 米。保持 0.18。
KICK_TARGET_MARK_SIZE_M = 0.18


